import { test, expect } from "@playwright/test";
import path from "node:path";
import fs from "node:fs";

// Load authoritative ground-truth oracle generated by scripts/generate_oracle.py
const ORACLE_PATH = path.resolve(__dirname, "../../test-fixtures/oracle.json");
const oracle = fs.existsSync(ORACLE_PATH)
  ? JSON.parse(fs.readFileSync(ORACLE_PATH, "utf-8"))
  : null;

test.describe("SWMS Multi-Page PDF Acceptance E2E (Strictly No Mocks)", () => {
  test.beforeEach(async () => {
    // Strictly verify no mocks are installed in this suite
  });

  test("Flow A: Upload 298-page Legal Textbook, verify multi-page indicator, canvas pixels, page navigation, highlight persistence and jump-to-source", async ({
    page
  }) => {
    test.setTimeout(120000); // 2 minutes for full end-to-end processing of 298-page PDF

    // 1. Navigate to workspace
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto("/workspace");
    await expect(page).toHaveURL(/.*workspace/);

    // 2. Open upload document modal
    const openUploadBtn = page.getByTestId("open-upload-pdf-btn");
    await expect(openUploadBtn).toBeVisible({ timeout: 15000 });
    await openUploadBtn.click();

    const uploadModal = page.getByTestId("upload-document-modal");
    await expect(uploadModal).toBeVisible();

    // 3. Upload real 298-page PDF via setInputFiles (Strictly NO MOCKS)
    const userPdfPath = path.resolve(
      __dirname,
      "../../test/Giáo trình Pháp luật đại cương_ebook.pdf"
    );
    expect(fs.existsSync(userPdfPath)).toBe(true);

    const fileInput = page.getByTestId("document-file-input");
    await fileInput.setInputFiles(userPdfPath);

    // Submit upload form
    const submitBtn = uploadModal.locator('button[type="submit"]');
    await submitBtn.click();

    // 4. Assert indicator shows 298 pages (fails on baseline due to 1-page facade)
    const pageIndicator = page.getByTestId("pdf-page-indicator");
    await expect(pageIndicator).toBeVisible({ timeout: 20000 });
    await expect(pageIndicator).toHaveText(/Trang 1 \/ 298/, { timeout: 10000 });

    // 5. Verify PDF canvas has non-blank rendered pixels (not blank or white)
    const canvas = page.locator("canvas.pdf-canvas").first();
    await expect(canvas).toBeVisible({ timeout: 10000 });
    await expect
      .poll(
        async () => {
          return await page.evaluate(() => {
            const c = document.querySelector("canvas.pdf-canvas") as HTMLCanvasElement | null;
            if (!c || c.width === 0 || c.height === 0) return false;
            const ctx = c.getContext("2d");
            if (!ctx) return false;
            const imgData = ctx.getImageData(0, 0, Math.min(c.width, 200), Math.min(c.height, 200)).data;
            for (let i = 0; i < imgData.length; i += 4) {
              const r = imgData[i];
              const g = imgData[i + 1];
              const b = imgData[i + 2];
              const a = imgData[i + 3];
              // Non-transparent and not purely white
              if (a > 0 && (r < 250 || g < 250 || b < 250)) {
                return true;
              }
            }
            return false;
          });
        },
        { timeout: 10000, intervals: [200, 500, 1000] }
      )
      .toBe(true);

    // 6. Navigate to middle page (Page 150)
    const pageInput = page.getByTestId("pdf-jump-page-input");
    await pageInput.fill("150");
    await pageInput.press("Enter");
    await expect(pageIndicator).toHaveText(/Trang 150 \/ 298/, { timeout: 10000 });

    // Assert page 150 extracted text matches oracle
    const textContainer = page.getByTestId("pdf-extracted-text-container");
    await expect(textContainer).toBeVisible();
    const p150Text = await textContainer.innerText();
    expect(p150Text).toContain("Được thành lập một cách hợp pháp theo quy định của Bộ luật Dân");

    // 7. Navigate to last page (Page 298)
    await pageInput.fill("298");
    await pageInput.press("Enter");
    await expect(pageIndicator).toHaveText(/Trang 298 \/ 298/, { timeout: 10000 });

    const p298Text = await textContainer.innerText();
    expect(p298Text).toContain("ISBN: 978-604-73-9848-5");

    // 8. Navigate to Page 200, create highlight and verify persistence across reload
    await pageInput.fill("200");
    await pageInput.press("Enter");
    await expect(pageIndicator).toHaveText(/Trang 200 \/ 298/, { timeout: 10000 });
    await expect(textContainer).toBeVisible({ timeout: 10000 });

    // Select text on page 200
    await page.evaluate(() => {
      const container = document.querySelector('[data-testid="pdf-extracted-text-container"]');
      if (container && container.firstChild) {
        const range = document.createRange();
        range.setStart(container.firstChild, 5);
        range.setEnd(container.firstChild, 55);
        const sel = window.getSelection();
        sel?.removeAllRanges();
        sel?.addRange(range);
        container.dispatchEvent(new MouseEvent("mouseup", { bubbles: true }));
      }
    });

    const yellowBtn = page.getByTestId("highlight-btn-yellow");
    await expect(yellowBtn).toBeVisible();
    await yellowBtn.click();

    // Verify mark exists on page 200
    const page200Mark = page.locator("mark[data-page='200']");
    await expect(page200Mark.first()).toBeVisible({ timeout: 5000 });

    // Reload browser and verify highlight persistence on page 200
    await page.reload();
    await page.waitForLoadState("networkidle");
    const openPdfBtn = page.getByRole("button", { name: "Mở PDF" }).first();
    if (await openPdfBtn.isVisible({ timeout: 5000 }).catch(() => false)) {
      await openPdfBtn.click();
    }
    await pageInput.fill("200");
    await pageInput.press("Enter");
    await expect(pageIndicator).toHaveText(/Trang 200 \/ 298/);
    await expect(page200Mark.first()).toBeVisible({ timeout: 10000 });

    // 9. Create flashcard from page 200 highlight and verify "Nhảy đến nguồn"
    await page200Mark.first().click();
    const toFlashcardBtn = page.getByTestId("to-flashcard-popover-trigger");
    await expect(toFlashcardBtn).toBeVisible();
    await toFlashcardBtn.click();

    // Set deterministic front text anchor
    const draftFrontInput = page.getByTestId("draft-front-input");
    await expect(draftFrontInput).toBeVisible();
    await draftFrontInput.fill("[Page 200 Legal Anchor] {{c1::hợp pháp}} theo quy định");

    const commitFlashcardBtn = page.getByTestId("commit-draft-flashcard-btn");
    await expect(commitFlashcardBtn).toBeVisible();
    await commitFlashcardBtn.click();

    // Switch to Review Mode (Mode 3)
    const reviewModeTab = page.getByTestId("mode-tab-review");
    await expect(reviewModeTab).toBeVisible();
    await reviewModeTab.click();

    // Deterministically advance to the target card
    let foundTargetCard = false;
    for (let i = 0; i < 15; i++) {
      const cardFront = await page.getByTestId("flashcard-front-face").innerText();
      if (cardFront.includes("[Page 200 Legal Anchor]")) {
        foundTargetCard = true;
        break;
      }
      const rateBtn = page.getByTestId("rate-btn-3");
      if (await rateBtn.isVisible()) {
        await rateBtn.click();
        await page.waitForTimeout(300);
      }
    }
    expect(foundTargetCard).toBe(true);

    // Flip card to reveal back face containing "Nhảy đến nguồn"
    const flipCard = page.getByTestId("fsrs-3d-flip-card");
    await expect(flipCard).toBeVisible({ timeout: 10000 });
    await flipCard.click();

    // Click "Nhảy đến nguồn"
    const jumpToSourceBtn = page
      .getByTestId("jump-to-source-btn")
      .or(page.getByRole("button", { name: /Nhảy đến nguồn/i }));
    await expect(jumpToSourceBtn.first()).toBeVisible({ timeout: 10000 });
    await jumpToSourceBtn.first().click();

    // Verify reader lands directly on page 200 with the quote highlighted and pulsed
    await expect(pageIndicator).toHaveText(/Trang 200 \/ 298/, { timeout: 15000 });
    await expect(page200Mark.first()).toBeVisible();
  });

  test("Flow B: Image-only scanned page displays 'Không có lớp văn bản — chưa OCR' badge", async ({
    page
  }) => {
    test.setTimeout(60000);

    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto("/workspace");

    const openUploadBtn = page.getByTestId("open-upload-pdf-btn");
    await expect(openUploadBtn).toBeVisible({ timeout: 15000 });
    await openUploadBtn.click();

    const mixedPdfPath = path.resolve(__dirname, "../../test-fixtures/mixed-scanned-text.pdf");
    expect(fs.existsSync(mixedPdfPath)).toBe(true);

    const fileInput = page.getByTestId("document-file-input");
    await fileInput.setInputFiles(mixedPdfPath);

    const submitBtn = page.getByTestId("upload-document-modal").locator('button[type="submit"]');
    await submitBtn.click();

    const pageIndicator = page.getByTestId("pdf-page-indicator");
    await expect(pageIndicator).toBeVisible({ timeout: 15000 });

    // Jump to page 2 (image-only scanned page with no text layer)
    const pageInput = page.getByTestId("pdf-jump-page-input");
    await pageInput.fill("2");
    await pageInput.press("Enter");

    // Verify badge
    const noTextBadge = page.getByTestId("no-text-layer-badge");
    await expect(noTextBadge).toBeVisible({ timeout: 10000 });
    await expect(noTextBadge).toContainText("Không có lớp văn bản — chưa OCR");
  });
});
